mapper.select:
SELECT 
FROM TBL_FINANCING_PLAN
WHERE DELETE_FLAG = 0

    AND PLAN_TYPE = #{planType}


    AND PLAN_STATUS = #{planStatus}


    AND COMPANY_ID = #{companyId}


    AND PLAN_YEAR = #{planYear}


    AND CURRENCY_CODE = #{currencyCode}

ORDER BY CREATED_TIME DESC

mapper.update:
UPDATE TBL_FINANCING_PLAN
SET PLAN_STATUS = #{status}, UPDATED_TIME = SYSDATE
WHERE PLAN_ID = #{planId}

mapper.select:
SELECT COUNT(*)
FROM TBL_FINANCING_PLAN
WHERE DELETE_FLAG = 0

    AND PLAN_TYPE = #{planType}


    AND PLAN_STATUS = #{planStatus}


    AND COMPANY_ID = #{companyId}


    AND PLAN_YEAR = #{planYear}

SELECT COUNT(*) AS "totalPlans", SUM(CASE WHEN PLAN_STATUS = 'EXECUTING' THEN 1 ELSE 0 END) AS "executingPlans", NVL(SUM(PLAN_AMOUNT), 0) AS "totalAmount", CASE WHEN COUNT(*) > 0 THEN ROUND(SUM(CASE WHEN PLAN_STATUS = 'COMPLETED' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) ELSE 0 END AS "completionRate" FROM TBL_FINANCING_PLAN WHERE DELETE_FLAG = 0
AND PLAN_YEAR = #{planYear}
AND COMPANY_ID = #{companyId}

SELECT COUNT(*)
FROM TBL_FINANCING_PLAN
WHERE DELETE_FLAG = 0 AND PLAN_STATUS = #{status}

    AND PLAN_YEAR = #{planYear}


    AND COMPANY_ID = #{companyId}

SELECT TO_CHAR(CREATED_TIME, 'MM') AS "month", COUNT(*) AS "planCount", NVL(SUM(PLAN_AMOUNT), 0) AS "totalAmount" FROM TBL_FINANCING_PLAN WHERE DELETE_FLAG = 0
AND PLAN_YEAR = #{planYear}
GROUP BY TO_CHAR(CREATED_TIME, 'MM') ORDER BY TO_CHAR(CREATED_TIME, 'MM')
